-- Rollback for 20261102100000_p2_staff_profile_and_huddle.sql.
-- REFUSES while any designation, address, forced-change flag, solution_by or solved_by value exists: dropping the columns and tables
-- would destroy them. Export first:
--   select id, designation, must_change_password from profiles where designation is not null or must_change_password;
--   select * from staff_private;
--   select id, solution_by, solved_by from meeting_issues where solution_by is not null or solved_by is not null;
-- then clear them deliberately. (task_color is regenerated by the migration, so it does not block the rollback.)
-- Restores wa_send_huddle_reminder exactly as 20260929100000 defined it.
begin;
do $g$
begin
  if exists (select 1 from public.profiles where designation is not null or must_change_password) then
    raise exception 'rollback refused: profiles has designation / must_change_password values (export, then clear deliberately)';
  end if;
  if exists (select 1 from public.staff_private) then
    raise exception 'rollback refused: staff_private has rows (export, then delete deliberately)';
  end if;
  if exists (select 1 from public.meeting_issues where solution_by is not null or solved_by is not null) then
    raise exception 'rollback refused: meeting_issues has solution_by / solved_by values (export, then clear deliberately)';
  end if;
end $g$;

create or replace function public.wa_send_huddle_reminder(p_org_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_ist timestamp := (now() at time zone 'Asia/Kolkata');
  v_today date := v_now_ist::date;
  v_claimed integer;
  v_role public.user_role;
begin
  -- Atomic claim: only one caller per day passes, and only when past the
  -- cutoff and no log exists yet.
  update public.settings s
     set huddle_reminder_last_date = v_today
   where s.org_id = p_org_id
     and s.huddle_reminder_time is not null
     and v_now_ist::time >= s.huddle_reminder_time
     and (s.huddle_reminder_last_date is null or s.huddle_reminder_last_date < v_today)
     and not exists (
       select 1 from public.meeting_logs m
        where m.org_id = p_org_id and m.meeting_date = v_today
     );
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return 0;
  end if;

  foreach v_role in array array['master', 'operation_admin', 'sales_admin']::public.user_role[] loop
    insert into public.notifications (org_id, role, type, title, body)
    values (p_org_id, v_role, 'huddle_reminder', 'Daily huddle not logged yet',
            'No huddle log has been recorded for today. Open Daily Huddle to record it.');
  end loop;
  return 1;
end;
$$;

